  function openReleaseEdit(section,item,index){var c=configs[section];if(section==="agreements"&&index==null)item=Object.assign({product_code:state.releaseDetail.product_code,agreement_source:"historical",params:{},tags:[],enabled:1},item);state.editing={mode:"release",section:section,item:item,index:index};q("adminEditTitle").textContent=(index==null?"新增":"编辑")+"待发布"+c.title;var fields=c.fields.filter(function(field){return !(section==="agreements"&&field.name==="params")});q("adminEditForm").innerHTML=fields.map(function(field){return fieldHtml(field,item)}).join('')+(section==="agreements"?releaseAgreementParametersHtml(item):'')+(section==="constraints"?'<div id="constraintExpressionPreview" class="constraint-expression full-span"></div>':'');fields.filter(function(f){return["parameter","parameter_optional","parameter_output","tag","product"].indexOf(f.type)>=0}).forEach(function(f){var el=q("adminEditForm").elements[f.name];if(el)el.value=item[f.name]||''});if(section==="constraints"){Array.prototype.forEach.call(q("adminEditForm").querySelectorAll("select,input"),function(el){el.addEventListener("change",updateConstraintPreview);el.addEventListener("input",updateConstraintPreview)});updateConstraintPreview()}show(q("adminEditOverlay"))}
  q("adminEditForm").onsubmit=async function(e){
    e.preventDefault();if(state.readOnly)return toast("当前为只读演示，不能保存数据库修改。",7000);
    var button=q("saveAdminEdit"),saved=false;button.disabled=true;button.textContent="正在保存…";
    try{
      var c=configs[state.editing.section],item={};
      c.fields.forEach(function(field){var el=q("adminEditForm").elements[field.name];if(!el)return;var v=el.value;if(field.type==="number")v=v===""?null:Number(v);if(field.type==="boolean")v=Number(v);if(field.type==="json"){try{v=JSON.parse(v||(field.name==="tags"?'[]':'{}'))}catch(_){throw new Error(field.label+"不是有效JSON")}}item[field.name]=v});
      if(state.editing.mode==="release"&&state.editing.section==="agreements"){item.params={};Array.prototype.forEach.call(q("adminEditForm").querySelectorAll("[data-release-parameter]"),function(el){if(el.value==="")return;var value=el.value,type=el.dataset.valueType;if(type==="boolean")value=Number(value);else if(type==="number"||type==="ip_grade")value=Number(value);item.params[el.dataset.releaseParameter]=value})}
      if(state.editing.mode==="release"){
        var items=(state.releaseDetail.data[state.editing.section]||[]).slice();if(state.editing.index==null)items.push(item);else items[state.editing.index]=item;
        await api("/api/admin/product-releases/section/save",{method:"POST",body:JSON.stringify({release_id:state.releaseId,section:state.editing.section,items:items})});saved=true;hide(q("adminEditOverlay"));toast("已保存到待发布草稿，不影响当前运行数据");
        try{await loadReleaseDetail();await renderProductReleases()}catch(refreshError){toast("数据已保存，但页面刷新失败："+refreshError.message+"。请手动刷新页面。",9000)}
      }else{
        await api("/api/admin/upsert",{method:"POST",body:JSON.stringify({section:state.editing.section,item:item})});saved=true;hide(q("adminEditOverlay"));toast("保存成功");
        try{await load()}catch(refreshError){toast("数据已保存，但页面刷新失败："+refreshError.message+"。请手动刷新页面。",9000)}
      }
    }catch(err){toast((saved?"数据已保存，但后续操作失败：":"保存失败：")+err.message,9000)}finally{button.disabled=false;button.textContent="保存到数据库"}
  }
  async function toggleRow(section,row){if(state.readOnly)return toast("当前为只读演示，不能修改启用状态。",7000);var c=configs[section],id=row[c.pk],target=!Number(row.enabled);try{await api("/api/admin/toggle",{method:"POST",body:JSON.stringify({section:section,id:id,enabled:target})});toast(target?"已重新启用":"已停用");await load()}catch(e){toast("状态修改失败："+e.message,9000)}}
  async function archiveRow(section,row){if(state.readOnly)return toast("当前为只读演示，不能归档记录。",7000);var c=configs[section],id=row[c.pk];if(!confirm("归档 “"+id+"” 后不会参与推荐和计算，可随时重新启用。是否继续？"))return;try{await api("/api/admin/delete",{method:"POST",body:JSON.stringify({section:section,id:id})});toast("已归档，可通过‘已停用’按钮恢复");await load()}catch(e){toast("归档失败："+e.message,9000)}}
  async function purgeRow(section,row){if(state.readOnly)return toast("当前为只读演示，不能永久删除。",7000);var c=configs[section],id=row[c.pk];if(!confirm("永久删除 “"+id+"” 无法直接恢复，系统将检查引用并自动备份。确认继续？"))return;try{await api("/api/admin/purge",{method:"POST",body:JSON.stringify({section:section,id:id})});toast("已永久删除");await load()}catch(e){toast("永久删除失败："+e.message,10000)}}
  function fileToBase64(file){return new Promise(function(resolve,reject){var r=new FileReader();r.onload=function(){resolve(String(r.result).split(',')[1])};r.onerror=reject;r.readAsDataURL(file)})}
  async function loadReleaseDetail(){if(!state.releaseId){state.releaseDetail=null;return}state.releaseDetail=await api("/api/admin/product-releases/"+encodeURIComponent(state.releaseId))}
  function releaseStatusText(status){return{draft:"草稿",validated:"数据检查通过",active:"当前业务数据",superseded:"已被后续版本替代"}[status]||status}
  async function renderProductReleases(){
    setHeading("成品数据工作区","原始成品表先进入独立草稿；业务数据维护与两个HTTP模型服务完全分开，切换时不会调用模型计算。");
    var releases=state.data.product_releases||[];
    if(state.releaseId&&!releases.some(function(x){return x.release_id===state.releaseId})){state.releaseId=null;state.releaseDetail=null}
    if(!state.releaseId&&releases.length)state.releaseId=releases[0].release_id;
    if(state.releaseId&&(!state.releaseDetail||state.releaseDetail.release_id!==state.releaseId))await loadReleaseDetail();
    var manifest=state.data.runtime_manifest||{},integration=state.data.integration||{};
    var options=releases.map(function(x){return'<option value="'+esc(x.release_id)+'" '+(x.release_id===state.releaseId?'selected':'')+'>'+esc(x.product_name)+' · '+esc(x.product_code)+' · '+esc(releaseStatusText(x.status))+'</option>'}).join('');
    var readiness=integration.product_ready?'<span class="status-good">当前HTTP模型实算JSON可用于运行计算</span>':'<span class="status-bad">仅推荐/计算暂停，不影响数据维护和切换：'+esc(integration.model_data_sync_error||"HTTP服务尚未返回标准数值JSON")+'</span>';
    var html='<section class="admin-card"><div class="admin-toolbar"><h2>建立或导入成品草稿</h2><span>当前HTTP服务成品（仅运行状态）：<b>'+esc(manifest.product_code||"-")+'</b></span></div>'+ 
      '<div class="release-create-grid"><label>成品代号<input id="releaseProductCode" placeholder="填写新成品代号"></label><label>成品名称<input id="releaseProductName" placeholder="请输入成品名称"></label><button id="createReleaseBtn" class="button primary">新建空白业务草稿</button></div>'+ 
      '<div class="release-offline-actions"><button id="cloneCurrentReleaseBtn" class="button secondary">复制当前运行数据为草稿</button><label class="button secondary">选择离线发布包<input id="releasePackageFile" type="file" accept=".json,.iprelease" hidden></label><button id="importReleasePackageBtn" class="button secondary" disabled>导入为新草稿</button></div><p class="release-readiness">'+readiness+'</p></section>'+
      '<section class="admin-card" style="margin-top:14px"><div class="admin-toolbar"><h2>从历史成品表自动建立草稿</h2><span>无需先维护下拉字典或匹配当前模型</span></div><p class="admin-lifecycle-note">上传包含价格和全部属性的普通 CSV/XLSX。系统只推断业务字段类型、允许值和是否必填；不会读取或比较当前价格/效能HTTP服务。</p><div class="release-create-grid"><label>新成品代号<input id="historyProductCode" placeholder="可与当前HTTP服务成品不同"></label><label>新成品名称<input id="historyProductName" placeholder="请输入成品名称"></label><label>缺失/空识别符<input id="historyMissingTokens" value="-1,\\,/" placeholder="例如：-1,\\,/，空单元格自动识别"></label></div><label class="upload-box" style="display:block;margin-top:12px">选择历史成品 CSV/XLSX<input id="historyProductFile" type="file" accept=".csv,.xlsx"></label><div class="release-offline-actions"><button id="previewHistoryBtn" class="button secondary">仅分析预览</button><button id="createHistoryReleaseBtn" class="button primary" disabled>按推断结果建立草稿</button></div><div id="historyInferenceReport"></div></section>'+ 
      '<section class="admin-card" style="margin-top:14px"><div class="admin-toolbar"><h2>草稿工作区</h2><select id="releaseSelector"><option value="">请选择待发布成品</option>'+options+'</select></div>';
    if(!state.releaseDetail){
      html+='<p>尚无草稿。可以新建空白草稿、复制当前运行数据，或从另一台电脑导出的离线发布包恢复。</p></section>';
      q("adminPanel").innerHTML=html;wireReleaseHeader();return
    }
    var d=state.releaseDetail,editable=d.status!=="active"&&d.status!=="superseded",sections=["products","parameters","tags","tag_rules","couplings","constraints","agreements"];
    html+='<div class="release-summary"><div><span>发布编号</span><b>'+esc(d.release_id)+'</b></div><div><span>状态</span><b>'+esc(releaseStatusText(d.status))+'</b></div><div><span>最后修改</span><b>'+esc(d.updated_at)+'</b></div></div>'+ 
      '<div class="release-offline-actions"><a class="button secondary" href="/api/admin/product-releases/maintenance/workbook?release_id='+encodeURIComponent(d.release_id)+'">下载自动维护工作簿</a>'+(editable?'<label class="button secondary">选择已修改工作簿<input id="releaseMaintenanceFile" type="file" accept=".xlsx" hidden></label><label><input id="releaseMaintenanceSkipInvalid" type="checkbox"> 跳过格式错误行</label><button id="importMaintenanceWorkbookBtn" class="button primary" disabled>导入到当前草稿</button>':'')+'</div>'+ 
      '<div class="release-module-tabs">'+sections.map(function(s){return'<button class="'+(state.releaseSection===s?'active':'')+'" data-release-section="'+s+'">'+esc(configs[s].title)+' <small>'+(d.data[s]||[]).length+'</small></button>'}).join('')+'</div>'+
      '<div id="releaseModulePanel">'+releaseModuleHtml(editable)+'</div><div id="releaseValidationReport">'+releaseValidationHtml(d.validation)+'</div>'+
      '<div class="release-actions"><button id="validateReleaseBtn" class="button secondary">检查业务数据（可选）</button><button id="activateReleaseBtn" class="button accent">备份并切换业务数据</button><a class="button secondary" href="/api/admin/product-releases/package?release_id='+encodeURIComponent(d.release_id)+'">导出完整离线发布包</a>'+(editable?'<button id="deleteReleaseBtn" class="button secondary">删除草稿</button>':'')+'</div></section>';
    q("adminPanel").innerHTML=html;wireReleaseHeader();wireReleaseModule(editable);wireReleaseMaintenance(editable);q("validateReleaseBtn").onclick=validateRelease;q("activateReleaseBtn").onclick=activateRelease;if(q("deleteReleaseBtn"))q("deleteReleaseBtn").onclick=deleteRelease;applyReadOnly()
  }
  function wireReleaseHeader(){q("createReleaseBtn").onclick=createRelease;q("cloneCurrentReleaseBtn").onclick=cloneCurrentRelease;q("releasePackageFile").onchange=function(){state.releasePackageFile=this.files[0]||null;q("importReleasePackageBtn").disabled=!state.releasePackageFile||state.readOnly};q("importReleasePackageBtn").onclick=importReleasePackage;q("historyProductFile").onchange=function(){state.historyFile=this.files[0]||null;state.historyPreview=null;q("createHistoryReleaseBtn").disabled=true;q("historyInferenceReport").innerHTML=""};q("previewHistoryBtn").onclick=previewHistoricalProducts;q("createHistoryReleaseBtn").onclick=createHistoricalRelease;q("releaseSelector").onchange=async function(){state.releaseId=this.value||null;state.releaseDetail=null;state.releasePreview=null;await renderProductReleases()}}
  function historyPayload(){return{product_code:q("historyProductCode").value.trim(),product_name:q("historyProductName").value.trim(),missing_tokens:q("historyMissingTokens").value,filename:state.historyFile?state.historyFile.name:""}}
  function historyInferenceHtml(report){var fields=report.inferred_parameters||[];return'<div class="import-summary"><div><span>历史成品</span><b>'+report.row_count+'</b></div><div><span>识别属性</span><b>'+report.attribute_count+'</b></div><div><span>非必填属性</span><b>'+report.optional_attribute_count+'</b></div><div><span>需要确认</span><b class="'+(report.needs_confirmation_count?'status-bad':'status-good')+'">'+report.needs_confirmation_count+'</b></div></div>'+((report.warnings||[]).map(function(x){return'<p>提醒：'+esc(x)+'</p>'}).join(''))+'<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>原始列</th><th>字段编号</th><th>推断类型</th><th>必填</th><th>缺失数</th><th>状态</th></tr></thead><tbody>'+fields.slice(0,80).map(function(x){return'<tr><td>'+esc(x.source_header)+'</td><td>'+esc(x.parameter_id)+'</td><td>'+esc(enumText("value_type",x.value_type))+'</td><td>'+(Number(x.required)?'是':'否')+'</td><td>'+esc(x.missing_count)+'</td><td class="'+(x.confidence==='needs_confirmation'?'status-bad':'status-good')+'">'+(x.confidence==='needs_confirmation'?'需确认':'高')+'</td></tr>'}).join('')+'</tbody></table></div>'}
  async function previewHistoricalProducts(){if(!state.historyFile)return toast("请先选择历史成品 CSV/XLSX");var payload=historyPayload();if(!payload.product_code||!payload.product_name)return toast("请填写新成品代号和名称");try{payload.file_base64=await fileToBase64(state.historyFile);state.historyPreview=await api("/api/admin/product-releases/history/preview",{method:"POST",body:JSON.stringify(payload)});q("historyInferenceReport").innerHTML=historyInferenceHtml(state.historyPreview);q("createHistoryReleaseBtn").disabled=state.readOnly;toast("自动推断完成；请重点确认标红的0/1或全缺失字段",7000)}catch(e){toast("历史成品分析失败："+e.message,10000)}}
  async function createHistoricalRelease(){if(state.readOnly||!state.historyFile)return;var payload=historyPayload();try{payload.file_base64=await fileToBase64(state.historyFile);var result=await api("/api/admin/product-releases/history/create",{method:"POST",body:JSON.stringify(payload)});state.releaseId=result.release.release_id;state.releaseDetail=result.release;state.releaseSection="parameters";state.historyPreview=null;await load();toast("已建立可编辑草稿；现在可下载维护工作簿或直接逐项修改",9000)}catch(e){toast("建立自动草稿失败："+e.message,11000)}}
  function wireReleaseMaintenance(editable){if(!editable)return;q("releaseMaintenanceFile").onchange=function(){state.releaseMaintenanceFile=this.files[0]||null;q("importMaintenanceWorkbookBtn").disabled=!state.releaseMaintenanceFile||state.readOnly};q("importMaintenanceWorkbookBtn").onclick=importMaintenanceWorkbook}
  async function importMaintenanceWorkbook(){if(!state.releaseMaintenanceFile)return toast("请先选择已修改的维护工作簿");try{var result=await api("/api/admin/product-releases/maintenance/import",{method:"POST",body:JSON.stringify({release_id:state.releaseId,filename:state.releaseMaintenanceFile.name,file_base64:await fileToBase64(state.releaseMaintenanceFile),skip_invalid:q("releaseMaintenanceSkipInvalid").checked})});state.releaseDetail=result.release;state.releaseMaintenanceFile=null;await load();toast("维护工作簿已导入草稿；当前运行数据没有变化",9000)}catch(e){toast("维护工作簿导入失败："+e.message,11000)}}
  function releaseModuleHtml(editable){var section=state.releaseSection,c=configs[section],rows=state.releaseDetail.data[section]||[];var template='<a class="button secondary" href="/api/admin/product-releases/module/template?release_id='+encodeURIComponent(state.releaseId)+'&section='+encodeURIComponent(section)+'">下载本模块CSV模板</a>';var importBox=editable?'<div class="release-import-box"><label class="upload-box">选择 '+esc(c.title)+' CSV/XLSX 文件<input id="releaseModuleFile" type="file" accept=".csv,.xlsx"></label><label><input id="releaseSkipInvalid" type="checkbox"> 暂存时跳过格式错误行</label><button id="previewReleaseFileBtn" class="button secondary">解析预览</button><button id="stageReleaseFileBtn" class="button primary" disabled>暂存到草稿</button></div><div id="releaseImportReport"></div>':'';var add=editable?'<button id="addReleaseRow" class="button primary">＋ 界面新增</button>':'';return'<div class="admin-toolbar"><h2>'+esc(c.title)+'（'+rows.length+'）</h2><div class="release-toolbar-actions">'+template+add+'</div></div><p class="admin-lifecycle-note">可直接在界面逐条维护，也可上传独立CSV/XLSX覆盖本模块。暂存不会修改当前运行数据库。</p>'+importBox+'<div class="admin-table-wrap"><table class="admin-table"><thead><tr>'+c.columns.map(function(x){return'<th>'+esc(x[1])+'</th>'}).join('')+(editable?'<th>草稿操作</th>':'')+'</tr></thead><tbody>'+rows.map(function(row,index){return'<tr>'+c.columns.map(function(x){var value=row[x[0]];if(typeof value==="object")value=JSON.stringify(value);return'<td>'+esc(enumText(x[0],value))+'</td>'}).join('')+(editable?'<td><div class="row-actions"><button class="release-edit" data-index="'+index+'">编辑</button><button class="release-delete danger" data-index="'+index+'">删除</button></div></td>':'')+'</tr>'}).join('')+'</tbody></table></div>'}
  function wireReleaseModule(editable){Array.prototype.forEach.call(document.querySelectorAll("[data-release-section]"),function(button){button.onclick=function(){state.releaseSection=button.dataset.releaseSection;state.releasePreview=null;renderProductReleases()}});if(!editable)return;q("addReleaseRow").onclick=function(){openReleaseEdit(state.releaseSection,{},null)};Array.prototype.forEach.call(document.querySelectorAll(".release-edit"),function(button){button.onclick=function(){var index=Number(button.dataset.index);openReleaseEdit(state.releaseSection,state.releaseDetail.data[state.releaseSection][index],index)}});Array.prototype.forEach.call(document.querySelectorAll(".release-delete"),function(button){button.onclick=async function(){var index=Number(button.dataset.index),items=(state.releaseDetail.data[state.releaseSection]||[]).slice();if(!confirm("仅从当前草稿删除该记录，是否继续？"))return;items.splice(index,1);await saveReleaseSection(items);toast("已从草稿删除")}});q("releaseModuleFile").onchange=function(){state.releaseFile=this.files[0]||null;state.releasePreview=null;q("stageReleaseFileBtn").disabled=true;q("releaseImportReport").innerHTML=""};q("previewReleaseFileBtn").onclick=previewReleaseFile;q("stageReleaseFileBtn").onclick=stageReleaseFile}
  async function createRelease(){if(state.readOnly)return;var code=q("releaseProductCode").value.trim(),name=q("releaseProductName").value.trim();if(!code||!name)return toast("请填写成品代号和名称");try{var result=await api("/api/admin/product-releases/create",{method:"POST",body:JSON.stringify({product_code:code,product_name:name,seed_schema:false})});state.releaseId=result.release_id;state.releaseDetail=result;state.releaseSection="parameters";await load();toast("空白业务草稿已创建；不会读取当前HTTP模型字段")}catch(e){toast("创建失败："+e.message,9000)}}
  async function cloneCurrentRelease(){if(state.readOnly)return;try{var result=await api("/api/admin/product-releases/clone-current",{method:"POST",body:"{}"});state.releaseId=result.release_id;state.releaseDetail=result;state.releaseSection="products";await load();toast("当前运行数据已完整复制为独立草稿")}catch(e){toast("复制失败："+e.message,9000)}}
  async function importReleasePackage(){if(state.readOnly||!state.releasePackageFile)return;try{var result=await api("/api/admin/product-releases/package/import",{method:"POST",body:JSON.stringify({filename:state.releasePackageFile.name,file_base64:await fileToBase64(state.releasePackageFile)})});state.releaseId=result.release_id;state.releaseDetail=result;state.releasePackageFile=null;state.releaseSection="products";await load();toast("离线发布包完整性校验通过，已导入为新草稿",8000)}catch(e){toast("发布包导入失败："+e.message,10000)}}
  async function saveReleaseSection(items){state.releaseDetail=await api("/api/admin/product-releases/section/save",{method:"POST",body:JSON.stringify({release_id:state.releaseId,section:state.releaseSection,items:items})});await loadReleaseDetail();renderProductReleases()}
