  async function activateRelease(){if(!confirm("系统会先备份SQLite，再切换成品业务数据。此操作不会调用价格或效能HTTP服务，也不会重新计算历史成品。是否继续？"))return;try{var result=await api("/api/admin/product-releases/activate",{method:"POST",body:JSON.stringify({release_id:state.releaseId})});var ready=result.runtime_readiness&&result.runtime_readiness.ready;toast(ready?"业务数据已切换，当前HTTP模型可用于计算":"业务数据已切换；HTTP模型尚未对应，仅推荐和计算暂停",10000);await load()}catch(e){toast("业务数据切换失败："+e.message,12000)}}
