  function coverageHtml(c){c=c||{};var missing=[].concat(c.missing_enabled_in_probe||[],c.missing_price_schema_in_probe||[],c.missing_effectiveness_schema_in_probe||[]).filter(function(x,i,a){return a.indexOf(x)===i}),empty=c.empty_value_fields||[],ok=!missing.length&&!empty.length;return'<div class="generation-report '+(ok?'success':'')+'"><b>完整参数JSON覆盖诊断</b><br>DataMaster启用 '+(c.enabled_business_field_count||0)+' 项；价格Schema '+(c.price_schema_field_count||0)+' 项；效能Schema '+(c.effectiveness_schema_field_count||0)+' 项；最终JSON '+(c.probe_field_count||0)+' 项。'+(missing.length?'<br><span class="status-bad">JSON缺少字段：'+esc(missing.join('、'))+'</span>':'<br><span class="status-good">字段集合已完整。</span>')+(empty.length?'<br><span class="status-bad">字段已发送但尚无值：'+esc(empty.join('、'))+'</span>':'')+'</div>'}
  function renderModels(){var manifest=state.data.runtime_manifest||{},serviceMode=manifest.execution_mode==="independent_http_services";setHeading("模型服务监测",serviceMode?"这里只读取HTTP健康状态与在线Schema，并按当前成品属性生成完整示例请求；不读取本地模型文件。":"当前为本地兼容模式，可维护项目内置JSON模型。");if(serviceMode){var snapshot=state.data.model_services||{},services=snapshot.services||{},examples=snapshot.request_examples||{};function card(kind,label){var item=services[kind]||{},health=item.health||{},schema=item.schema||{},example=examples[kind]||{};return'<section class="admin-card"><h2>'+label+' HTTP服务</h2><p>地址：<b>'+esc(item.url||'-')+'</b></p><p>健康状态：<b class="'+(health.status==='ok'||health.status==='healthy'?'status-good':'status-bad')+'">'+esc(health.status||'不可用')+'</b></p>'+(item.schema_error?'<p class="status-bad">Schema读取失败：'+esc(item.schema_error)+'</p>':'<p>成品代号：<b>'+esc(schema.product_code||'-')+'</b> · 版本 '+esc(schema.model_version||'-')+' · 字段 '+((schema.fields||[]).length)+'</p>')+'<h3>按完整参数并集生成的示例JSON</h3><pre style="white-space:pre-wrap;word-break:break-all;background:#f6f8fb;padding:12px;border-radius:10px">'+esc(JSON.stringify(example,null,2))+'</pre></section>'}q("adminPanel").innerHTML='<div class="generation-report"><b>本地模型读取：已关闭</b><br>业务成品：'+esc(snapshot.current_business_product_code||'-')+'。示例JSON包含DataMaster启用字段与双服务Schema字段的并集。</div>'+coverageHtml(snapshot.parameter_coverage)+'<div class="model-drop-grid">'+card("price","价格")+card("effectiveness","效能")+'</div>';return}var table='<section class="admin-card"><h2>本地兼容模型</h2>'+state.data.models.map(function(m){return'<p><b>'+esc(enumText("model_kind",m.model_kind))+'</b> · '+esc(m.model_version)+'</p>'}).join('')+'</section>';q("adminPanel").innerHTML=table+'<section class="admin-card" style="margin-top:14px"><h2>替换本地兼容模型</h2><p style="font-size:.7rem;color:#667085">必须同时选择 effectiveness_bundle.json 与 price_bundle.json。</p><div class="model-drop-grid"><label class="upload-box">效能模型<input id="effModelFile" type="file" accept=".json"></label><label class="upload-box">价格模型<input id="priceModelFile" type="file" accept=".json"></label></div><button id="replaceModelsBtn" class="button primary" style="margin-top:12px">校验并替换</button><div id="modelReplaceReport"></div></section>';q("replaceModelsBtn").onclick=replaceModels}
  async function replaceModels(){if(state.readOnly)return toast("当前为只读演示，不能替换模型文件。",7000);var ef=q("effModelFile").files[0],pf=q("priceModelFile").files[0];if(!ef||!pf)return toast("请同时选择两个模型文件");try{var r=await api("/api/admin/models/replace",{method:"POST",body:JSON.stringify({effectiveness_base64:await fileToBase64(ef),price_base64:await fileToBase64(pf)})});q("modelReplaceReport").innerHTML='<div class="generation-report '+(r.replaced?'success':'')+'"><b>'+(r.replaced?'替换成功':'替换失败')+'</b><br>'+(r.contract.errors||[]).map(esc).join('<br>')+(r.contract.warnings||[]).map(function(x){return'<br>警告：'+esc(x)}).join('')+'</div>';if(r.replaced){toast("两个模型已替换并立即生效");await load()}}catch(e){toast("模型替换失败："+e.message,9000)}}
  function renderDataMaster(){setHeading("主数据工作簿","工作簿只负责业务主数据；价格和效能HTTP服务的成品代号、字段和必填策略不在这里校验。");q("adminPanel").innerHTML='<section class="admin-card"><div class="admin-toolbar"><h2>主数据工作簿导入 / 导出</h2><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="button secondary" href="/api/admin/datamaster/current">导出当前主数据工作簿</a><a class="button secondary" href="/api/admin/datamaster/template">下载引导式模板</a></div></div><div class="datamaster-flow"><div><b>1. 导出或下载模板</b><p>先阅读“填写说明”，所有类型和引用字段优先使用下拉选择。</p></div><div><b>2. 上传并检查</b><p>只检查业务表结构、编号重复、标签/耦合/约束引用，不连接HTTP模型。</p></div><div><b>3. 一次性切换</b><p>先备份数据库，再写入业务数据；历史成品不在导入时计算模型结果。</p></div></div><label class="upload-box" style="display:block;margin-top:14px">选择主数据工作簿<input id="dataMasterFile" type="file" accept=".xlsx"></label><div style="margin-top:12px;display:flex;gap:8px"><button id="dataMasterPreviewBtn" class="button primary">检查表格结构</button><button id="dataMasterCommitBtn" class="button accent" disabled>备份并切换业务数据</button></div><div id="dataMasterReport"></div></section>';q("dataMasterFile").onchange=function(){state.dataMasterFile=this.files[0]||null;state.dataMasterPreview=null;q("dataMasterCommitBtn").disabled=true};q("dataMasterPreviewBtn").onclick=previewDataMaster;q("dataMasterCommitBtn").onclick=commitDataMaster}
  function renderDataMasterReport(r){var counts=r.counts||{};q("dataMasterReport").innerHTML='<div class="generation-report '+(r.valid?'success':'')+'"><b>'+(r.valid?'业务数据结构可写入':'工作簿存在结构问题')+'</b><br>成品 '+(counts.products||0)+'；指标 '+(counts.parameters||0)+'；标签 '+(counts.tags||0)+'；标签规则 '+(counts.tag_rules||0)+'；耦合 '+(counts.couplings||0)+'；约束 '+(counts.constraints||0)+'；历史协议 '+(counts.agreements||0)+'</div>'+((r.errors||[]).length?'<div class="datamaster-errors"><h3>必须修正</h3>'+r.errors.map(function(x){return'<p>× '+esc(x)+'</p>'}).join('')+'</div>':'')+((r.warnings||[]).length?'<div class="datamaster-warnings"><h3>提醒</h3>'+r.warnings.map(function(x){return'<p>! '+esc(x)+'</p>'}).join('')+'</div>':'')}
  async function previewDataMaster(){if(!state.dataMasterFile)return toast("请先选择 .xlsx 主数据工作簿");try{var payload={filename:state.dataMasterFile.name,file_base64:await fileToBase64(state.dataMasterFile)};state.dataMasterPreview=await api("/api/admin/datamaster/preview",{method:"POST",body:JSON.stringify(payload)});renderDataMasterReport(state.dataMasterPreview);q("dataMasterCommitBtn").disabled=!state.dataMasterPreview.valid||state.readOnly;applyReadOnly();toast(state.dataMasterPreview.valid?"业务表结构检查完成；未调用HTTP模型":"工作簿存在结构问题",7000)}catch(e){toast("主数据工作簿解析失败："+e.message,10000)}}
  async function commitDataMaster(){if(state.readOnly)return toast("当前为只读演示，只能查看和预览主数据工作簿。",7000);if(!state.dataMasterFile||!state.dataMasterPreview||!state.dataMasterPreview.valid)return toast("请先完成业务表结构检查");if(!confirm("系统将先备份数据库，再以该工作簿切换成品业务数据。不会调用价格或效能HTTP服务。是否继续？"))return;try{var payload={filename:state.dataMasterFile.name,file_base64:await fileToBase64(state.dataMasterFile)};var r=await api("/api/admin/datamaster/commit",{method:"POST",body:JSON.stringify(payload)});renderDataMasterReport(r);toast("业务数据已切换，主数据版本 "+r.commit_result.master_data_version,8000);await load();state.section="datamaster";renderDataMaster()}catch(e){toast("主数据工作簿提交失败："+e.message,12000)}}
  function renderWideImport(){setHeading("协议宽表导入","恢复CSV/XLSX宽表解析。效能属性即完整成品属性，缺失任一必填属性的行不会静默补最小值；价格模型按自身缺失策略处理。");q("adminPanel").innerHTML='<section class="admin-card"><div class="admin-toolbar"><h2>导入历史技术协议</h2><a class="button secondary" href="/api/admin/wide-import/template">下载宽表模板</a></div><p style="font-size:.7rem;color:#667085">支持 .csv 与 .xlsx。指标列可使用数据库中的指标名称或指标编号；标签可填写标签名称或编号，并用顿号、逗号或分号分隔。</p><div class="model-drop-grid"><label class="upload-box">选择协议宽表<input id="wideFile" type="file" accept=".csv,.xlsx"></label><div class="upload-box"><label><input id="wideOverwrite" type="checkbox"> 覆盖数据库中同编号协议</label><label style="display:block;margin-top:10px"><input id="wideSkipInvalid" type="checkbox"> 提交时跳过无效行</label></div></div><div style="margin-top:12px;display:flex;gap:8px"><button id="widePreviewBtn" class="button primary">解析并预览</button><button id="wideCommitBtn" class="button accent" disabled>确认导入有效记录</button></div><div id="wideReport"></div></section>';q("wideFile").onchange=function(){state.wideFile=this.files[0]||null;state.widePreview=null;q("wideCommitBtn").disabled=true};q("widePreviewBtn").onclick=previewWide;q("wideCommitBtn").onclick=commitWide}
  function renderWideReport(r){var rows=(r.rows||[]).slice(0,80);q("wideReport").innerHTML='<div class="import-summary"><div><span>总行数</span><b>'+r.row_count+'</b></div><div><span>有效</span><b class="status-good">'+r.valid_count+'</b></div><div><span>无效</span><b class="'+(r.invalid_count?'status-bad':'status-good')+'">'+r.invalid_count+'</b></div></div>'+((r.global_warnings||[]).length?'<div class="generation-report">'+r.global_warnings.map(esc).join('<br>')+'</div>':'')+'<div class="import-errors">'+rows.map(function(x){return'<div class="import-row '+(x.valid?'valid':'invalid')+'"><b>第 '+x.row_number+' 行 · '+esc((x.item||{}).agreement_id||'未填写编号')+' · '+esc((x.item||{}).agreement_name||'未填写名称')+'</b>'+(x.errors||[]).map(function(v){return'<div>错误：'+esc(v)+'</div>'}).join('')+(x.warnings||[]).map(function(v){return'<div>提醒：'+esc(v)+'</div>'}).join('')+'</div>'}).join('')+'</div>'+(r.row_count>80?'<p>仅显示前80行。</p>':'')}
  async function previewWide(){if(!state.wideFile)return toast("请先选择CSV或XLSX宽表");try{var payload={filename:state.wideFile.name,file_base64:await fileToBase64(state.wideFile)};state.widePreview=await api("/api/admin/wide-import/preview",{method:"POST",body:JSON.stringify(payload)});renderWideReport(state.widePreview);q("wideCommitBtn").disabled=state.widePreview.valid_count===0||state.readOnly;applyReadOnly();toast("宽表解析完成") }catch(e){toast("宽表解析失败："+e.message,9000)}}
  async function commitWide(){if(state.readOnly)return toast("当前为只读演示，只能解析预览，不能提交导入。",7000);if(!state.wideFile||!state.widePreview)return toast("请先解析预览");if(!confirm("确认将有效记录写入协议数据库？"))return;try{var payload={filename:state.wideFile.name,file_base64:await fileToBase64(state.wideFile),overwrite:q("wideOverwrite").checked,skip_invalid:q("wideSkipInvalid").checked};var r=await api("/api/admin/wide-import/commit",{method:"POST",body:JSON.stringify(payload)});renderWideReport(r);toast("导入完成：新增 "+r.commit_result.inserted+"，更新 "+r.commit_result.updated);await load();state.section="wide_import";renderWideImport()}catch(e){toast("导入失败："+e.message,10000)}}
  async function renderDatabase(){setHeading("数据库备份与恢复","支持下载当前 SQLite 数据库、创建备份、恢复历史备份，以及上传以前保存的数据库。所有恢复操作都会先备份当前数据库。");var backups=await api("/api/admin/backups");q("adminPanel").innerHTML='<section class="admin-card"><div class="backup-actions"><a class="button secondary" href="/api/admin/database/download">下载当前数据库</a><button id="createBackup" class="button primary">立即创建备份</button><button id="exportJson" class="button secondary">导出完整JSON</button><label class="button secondary">上传数据库恢复<input id="uploadDb" type="file" accept=".db" hidden></label></div><p>完整性：<b class="'+(state.data.database.integrity.ok?'status-good':'status-bad')+'">'+(state.data.database.integrity.ok?'正常':'异常')+'</b>；大小 '+Math.round(state.data.database.size_bytes/1024)+' KB</p></section><section class="admin-card" style="margin-top:14px"><div class="admin-toolbar"><h2>历史备份</h2></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>文件名</th><th>大小</th><th>时间</th><th>操作</th></tr></thead><tbody>'+backups.items.map(function(b){return'<tr><td>'+esc(b.name)+'</td><td>'+Math.round(b.size_bytes/1024)+' KB</td><td>'+esc(b.modified_at)+'</td><td><button class="edit-row restore-backup" data-name="'+esc(b.name)+'">恢复</button></td></tr>'}).join('')+'</tbody></table></div></section>';q("createBackup").onclick=async function(){await api("/api/admin/backup",{method:"POST",body:"{}"});toast("备份已创建");renderDatabase()};q("exportJson").onclick=async function(){var d=await api("/api/admin/export-json");download("industrial_protocol_database.json",JSON.stringify(d,null,2),"application/json")};q("uploadDb").onchange=uploadDatabase;Array.prototype.forEach.call(document.querySelectorAll(".restore-backup"),function(b){b.onclick=async function(){if(!confirm("恢复该备份会替换当前数据库，是否继续？"))return;await api("/api/admin/restore-backup",{method:"POST",body:JSON.stringify({name:b.dataset.name})});toast("数据库已恢复");await load()}})}
  async function uploadDatabase(){if(state.readOnly)return toast("当前为只读演示，不能上传恢复数据库。",7000);var file=this.files[0];if(!file)return;if(!confirm("上传恢复会替换当前数据库，系统会先自动备份。是否继续？"))return;try{await api("/api/admin/upload-database",{method:"POST",body:JSON.stringify({database_base64:await fileToBase64(file)})});toast("上传数据库已恢复");await load()}catch(e){toast("恢复失败："+e.message,9000)}}
